[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-obstetrics-gynecology",
  "answer": "임신 10주에 2주간 1일 3~4회 구토 + 3kg(대략 3% 이상) 체중 감소 + 물만 겨우 섭취 + 기립성 어지럼 + 이전 임신 입덧 입원력은 hyperemesis gravidarum(HG) 가능성이 높은 조합이며, 이미 탈수·케톤증·전해질 이상이 진행되었을 가능성을 시사합니다. 지금은 자가 관리로 지켜볼 단계가 아니라 같은 날(가능하면 즉시) 대면 평가가 필요한 상태로 보아야 하며, Wernicke 뇌병증·중증 전해질 이상을 배제할 때까지 응급 수준으로 다루어야 합니다.",
  "red_flag": {
    "present": true,
    "items": [
      { "id": "OG_desync_or_volume_depletion_suspected", "evidence": "2주간 1일 3~4회 구토, 3kg 체중감소, 물만 겨우 섭취, 기립성 어지럼 — 경구 섭취 불가 + 체액 결핍 시사", "basis": "history" },
      { "id": "R_series_impaired_intake", "evidence": "'물만 겨우 섭취' — 24시간 이상 경구 섭취 유지 못하는 상태는 응급 평가 대상", "basis": "history" },
      { "id": "OG6_OG5_확장_감별필요", "evidence": "자간전증 징후(두통·시야 이상·상복부 통증·부종) 미확인 — 확인되지 않았으나 배제되지 않음", "basis": "history" },
      { "id": "OG2_질출혈", "evidence": "질 출혈 여부 미확인 — 임신 중 출혈은 별도 응급 감별", "basis": "history" }
